"""Retriever utilities"""
from typing import List, Dict, Any

from .chroma_client import ChromaClient


class Retriever:
    """Document retriever using Chroma"""

    def __init__(self, chroma_client: ChromaClient) -> None:
        self.client = chroma_client

    def get_relevant_docs(self, query: str, k: int = 4) -> List[Dict[str, Any]]:
        """Retrieve relevant documents for a query"""
        results = self.client.query(query, n_results=k)

        documents: List[Dict[str, Any]] = []

        # Check if results contain documents
        if not results.get("documents") or not results["documents"][0]:
            return documents

        docs_list = results["documents"][0]
        metadatas_list = results.get("metadatas") or [[]]
        distances_list = results.get("distances") or [[]]

        for i, doc in enumerate(docs_list):
            metadata = metadatas_list[0][i] if metadatas_list[0] else {}
            distance = distances_list[0][i] if distances_list[0] else None
            documents.append({
                "content": doc,
                "metadata": metadata,
                "distance": distance
            })

        return documents

